int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{
 if(argc!=8)throw std::runtime_error("checkpoint source_tag initial.dat output.csv nodes basis fit_degree_zero_interpolation");auto snap=cubed_sphere::CompositeCheckpoint::Read(argv[1],argv[2]);cubed_sphere::CompositeDifference g(snap.mesh,4,snap.radial_interface_stencils);if(g.active.size()>50000)throw std::runtime_error("bounded50000");
 V initial(g.active.size()*22,0);std::ifstream in(argv[3]);std::string magic;size_t size;in>>magic>>size;if(magic!="ISOTROPIC_M1_3"||size!=g.active.size())throw std::runtime_error("initial mismatch");for(size_t p=0;p<size;++p){Real r,chi,alpha,a,k;in>>r>>chi>>alpha>>a>>k;const auto &x=g.geometry[p].x;if(!in||std::abs(r-std::sqrt(x[0]*x[0]+x[1]*x[1]+x[2]*x[2]))>1e-13)throw std::runtime_error("initial geometry mismatch");initial[22*p]=std::log(chi);initial[22*p+18]=std::log(alpha/((1+r*r)/2));initial[22*p+13]=3+k;for(int t=0;t<6;++t){int i=h::kCompositeTensorI[t],j=h::kCompositeTensorJ[t];initial[22*p+7+t]=1.5*a*(x[i]*x[j]/(r*r)-(i==j?1./3:0));}}
 cubed_sphere::ScriSurface surface(g,22,snap.scri_radial_points);std::unique_ptr<cubed_sphere::RadialScriJetProbe> owned_plan;if(std::stoi(argv[7]))owned_plan=std::make_unique<cubed_sphere::AnchoredRadialScriProbe>(surface,std::stoi(argv[5]),cubed_sphere::RadialScriJetProbe::Basis(std::stoi(argv[6])),std::stoi(argv[7]));else owned_plan=std::make_unique<cubed_sphere::RadialScriJetProbe>(surface,std::stoi(argv[5]),cubed_sphere::RadialScriJetProbe::Basis(std::stoi(argv[6])));const auto &plan=*owned_plan;
 std::ofstream out(argv[4]);out<<std::setprecision(17)<<"state,row,face,j,k,x,y,z,qchi_G,qchi_H,qalpha_G,qalpha_H,chi_dn";const char*names[]={"chi","Khat","Theta","alpha","Axx","Axy","Axz","Ayy","Ayz","Azz","LambdaX","LambdaY","LambdaZ"};for(auto name:names)out<<','<<name;for(auto term:{"baseline","chi_normal","chi_tangent","metric_normal","metric_tangent","independent_lambda","curvature","sum_error"})out<<",Axx_"<<term;for(auto term:{"metric_normal","metric_tangent","independent_lambda","trace_normal","trace_tangent","curvature","sum_error"})for(int i=0;i<3;++i)out<<",Lambda"<<i<<'_'<<term;out<<'\n';Real largest[2]{},Axx[2]{},reconstruction=0;int at[2]{},component[2]{};
 for(int state=0;state<2;++state){const auto &data=state?snap.fields:initial;V padded(22*g.count,0);for(size_t p=0;p<g.active.size();++p)for(int f=0;f<22;++f)padded[f*g.count+g.active[p]]=data[22*p+f];V boundary=state?snap.boundary_fields:V(surface.values.size(),0);cubed_sphere::HermiteBoundaryProbe probe(surface,padded,boundary,22);plan.Apply(probe);
 for(size_t p=0;p<surface.rows.size();++p){const auto &row=surface.rows[p];const auto &x=row.geometry.x;Real q[3]={1,(row.j+.5)/g.n,(row.k+.5)/g.n};const auto sampled=probe.At(row.block,q);auto u=h::UnpackComposite(x,sampled.value,sampled.d,sampled.dd,true,0,2);Real beta[3];if(!h::FixedAngleScriShift(h::Geometry(u.metric),Real(1),u.chi.value,x,beta))throw std::runtime_error("invalid null datum");for(int i=0;i<3;++i)u.beta.value[i]=beta[i];const auto pole=Poles(u,x);Real dn=0;for(int i=0;i<3;++i)dn+=x[i]*u.chi.d[i];out<<state<<','<<p<<','<<g.mesh.blocks[row.block].face<<','<<row.j<<','<<row.k<<','<<x[0]<<','<<x[1]<<','<<x[2]<<','<<probe.normal_first[22*p]<<','<<probe.normal_second[22*p]<<','<<probe.normal_first[22*p+18]<<','<<probe.normal_second[22*p+18]<<','<<dn;for(int f=0;f<13;++f){out<<','<<pole[f];if(std::abs(pole[f])>largest[state]){largest[state]=std::abs(pole[f]);at[state]=p;component[state]=f;}}Axx[state]=std::max(Axx[state],std::abs(pole[4]));
 auto base=u;for(int i=0;i<3;++i){base.chi.d[i]=0;base.lambda.value[i]=0;for(int j=0;j<3;++j){base.a.k[i][j]=0;for(int a=0;a<3;++a)base.metric.dg[a][i][j]=0;}}Real pieces[8]{};pieces[0]=Poles(base,x)[4];for(int mode=1;mode<=6;++mode){auto v=base;if(mode<=2)for(int a=0;a<3;++a)v.chi.d[a]=mode==1?x[a]*dn:u.chi.d[a]-x[a]*dn;if(mode==3||mode==4)for(int i=0;i<3;++i)for(int j=0;j<3;++j){Real md=0;for(int a=0;a<3;++a)md+=x[a]*u.metric.dg[a][i][j];for(int a=0;a<3;++a)v.metric.dg[a][i][j]=mode==3?x[a]*md:u.metric.dg[a][i][j]-x[a]*md;}if(mode==5)for(int a=0;a<3;++a)v.lambda.value[a]=u.lambda.value[a];if(mode==6)for(int i=0;i<3;++i)for(int j=0;j<3;++j)v.a.k[i][j]=u.a.k[i][j];pieces[mode]=Poles(v,x)[4]-pieces[0];}Real sum=0;for(int i=0;i<7;++i)sum+=pieces[i];pieces[7]=sum-pole[4];reconstruction=std::max(reconstruction,std::abs(pieces[7]));for(Real v:pieces)out<<','<<v;
 const auto geo=h::Geometry(u.metric);auto radial_metric=u.metric;for(int i=0;i<3;++i)for(int j=0;j<3;++j){Real nd=0;for(int a=0;a<3;++a)nd+=x[a]*u.metric.dg[a][i][j];for(int a=0;a<3;++a)radial_metric.dg[a][i][j]=x[a]*nd;}const auto radial_geo=h::Geometry(radial_metric);Real terms[7][3]{};const Real factor=u.alpha.value*(4./3*(u.trace.value+2*u.theta.value)+8);Real trace_n=0;for(int j=0;j<3;++j)trace_n+=x[j]*(2*u.trace.d[j]+u.theta.d[j]);for(int i=0;i<3;++i){terms[0][i]=.5*factor*radial_geo.contracted[i];terms[1][i]=.5*factor*(geo.contracted[i]-radial_geo.contracted[i]);terms[2][i]=-.5*factor*u.lambda.value[i];for(int j=0;j<3;++j){terms[3][i]-=2./3*u.alpha.value*geo.inverse[i][j]*x[j]*trace_n;terms[4][i]-=2./3*u.alpha.value*geo.inverse[i][j]*(2*u.trace.d[j]+u.theta.d[j]-x[j]*trace_n);for(int a=0;a<3;++a)for(int b=0;b<3;++b)terms[5][i]+=4*u.alpha.value*geo.inverse[i][a]*geo.inverse[j][b]*u.a.k[a][b]*x[j];}Real total=0;for(int t=0;t<6;++t)total+=terms[t][i];terms[6][i]=total-pole[10+i];reconstruction=std::max(reconstruction,std::abs(terms[6][i]));}for(const auto&term:terms)for(Real v:term)out<<','<<v;out<<'\n';}}
 std::cout<<std::setprecision(17)<<"{\"basis\":\""<<plan.Name(plan.basis)<<"\",\"nodes\":"<<plan.requested<<",\"condition\":"<<plan.condition<<",\"reproduction\":"<<plan.reproduction<<",\"D1_ratio\":"<<plan.first_ratio<<",\"D2_ratio\":"<<plan.second_ratio<<",\"checkpoint_time\":"<<snap.step*snap.dt<<",\"cells\":"<<g.active.size()<<",\"initial_max_pole\":"<<largest[0]<<",\"initial_Axx\":"<<Axx[0]<<",\"evolved_max_pole\":"<<largest[1]<<",\"evolved_Axx\":"<<Axx[1]<<",\"evolved_row\":"<<at[1]<<",\"evolved_component\":\""<<names[component[1]]<<"\",\"Axx_decomposition_error\":"<<reconstruction<<",\"no_evolution_or_solve\":true}\n";if(reconstruction>1e-12)throw std::runtime_error("additive Axx decomposition failed");
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=2;}Kokkos::finalize();return code;}
